select id, store_name, city, region, opened_date, sqft, first_value(region, true) over w_hist as first_known_region, last_value(sqft) ignore nulls over w_hist as last_known_sqft, avg(sqft) over (partition by region, city order by sqft, id rows between 2 preceding and 1 preceding) as sqft_avg_2_prior, dense_rank() over (partition by region order by sqft nulls first) as sqft_dense_rank from stores window w_hist as (partition by city order by sqft, id rows between unbounded preceding and current row)
